-- 锻造师系统：扩展打造配方表 —— 补充体力/物防/魔防/MaxHP/MaxMP/材料4~8 列；
-- 删除原占位配方，写入全部 27 条正式锻造配方（enabled=1）。
-- 数据照甲方提供的配方原文整理，名称仅供展示，实际以 result_item_id / 材料ID 为准。
-- 品级下标：0=入门 1=普通 2=职业 3=大师 4=宗师（经验曲线见 org.gms.service.ForgeService.TIERS）。

ALTER TABLE `xy_forge_recipe`
    ADD COLUMN `stamina_cost` INT NOT NULL DEFAULT 0 COMMENT '打造消耗体力' AFTER `meso_cost`,
    ADD COLUMN `material4_item_id` INT DEFAULT NULL COMMENT '材料4物品ID(NULL表示不需要)',
    ADD COLUMN `material4_count` INT NOT NULL DEFAULT 0 COMMENT '材料4所需数量',
    ADD COLUMN `material5_item_id` INT DEFAULT NULL COMMENT '材料5物品ID(NULL表示不需要)',
    ADD COLUMN `material5_count` INT NOT NULL DEFAULT 0 COMMENT '材料5所需数量',
    ADD COLUMN `material6_item_id` INT DEFAULT NULL COMMENT '材料6物品ID(NULL表示不需要)',
    ADD COLUMN `material6_count` INT NOT NULL DEFAULT 0 COMMENT '材料6所需数量',
    ADD COLUMN `material7_item_id` INT DEFAULT NULL COMMENT '材料7物品ID(NULL表示不需要)',
    ADD COLUMN `material7_count` INT NOT NULL DEFAULT 0 COMMENT '材料7所需数量',
    ADD COLUMN `material8_item_id` INT DEFAULT NULL COMMENT '材料8物品ID(NULL表示不需要)',
    ADD COLUMN `material8_count` INT NOT NULL DEFAULT 0 COMMENT '材料8所需数量',
    ADD COLUMN `pdd_min` INT NOT NULL DEFAULT 0 COMMENT '物理防御力随机下限(0=不涉及)',
    ADD COLUMN `pdd_max` INT NOT NULL DEFAULT 0 COMMENT '物理防御力随机上限',
    ADD COLUMN `mdd_min` INT NOT NULL DEFAULT 0 COMMENT '魔法防御力随机下限(0=不涉及)',
    ADD COLUMN `mdd_max` INT NOT NULL DEFAULT 0 COMMENT '魔法防御力随机上限',
    ADD COLUMN `hp_min` INT NOT NULL DEFAULT 0 COMMENT 'MaxHP随机下限(0=不涉及)',
    ADD COLUMN `hp_max` INT NOT NULL DEFAULT 0 COMMENT 'MaxHP随机上限',
    ADD COLUMN `mp_min` INT NOT NULL DEFAULT 0 COMMENT 'MaxMP随机下限(0=不涉及)',
    ADD COLUMN `mp_max` INT NOT NULL DEFAULT 0 COMMENT 'MaxMP随机上限';

DELETE FROM `xy_forge_recipe`;

